    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    for color in range(10):
        for dr, dc in ((1, 1), (1, -1)):
            # Each adjacent diagonal same-color pair defines a line to extend to the edges.
            for r in range(h):
                for c in range(w):
                    if grid[r][c] != color:
                        continue
                    r2, c2 = r + dr, c + dc
                    if not (0 <= r2 < h and 0 <= c2 < w and grid[r2][c2] == color):
                        continue
                    # Walk both ways along the full diagonal, filling the background.
                    rr, cc = r, c
                    while 0 <= rr - dr < h and 0 <= cc - dc < w:
                        rr -= dr; cc -= dc
                    while 0 <= rr < h and 0 <= cc < w:
                        if out[rr][cc] != bg and out[rr][cc] != color:
                            break
                        out[rr][cc] = color
                        rr += dr; cc += dc
